pub fn unseal_node(
    sealed: &[u8],
    read_key: &[u8; 32],
    node_id: &str,
    kind: NodeKind,
    generation: u32,
) -> Result<Vec<u8>, NodeError> {
    let aad = build_node_aad(node_id, kind_byte(kind), generation, ROLE_BODY)?;
    let body = unseal_aes_gcm_aad(sealed, read_key, &aad)?;
    Ok(body)
}

