/// Discriminator for the three node kinds (mirrors TS `NodeKind`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NodeKind {
    Folder,
    File,
    Root,
}

impl NodeKind {
    /// The lowercase wire string for this kind (matches TS `NodeKind` literal values).
    pub fn as_str(&self) -> &'static str {
        match self {
            NodeKind::Folder => "folder",
            NodeKind::File => "file",
            NodeKind::Root => "root",
        }
    }
}

/// One historical version of a file node's content (mirrors TS `VersionEntry`).
///
/// `file_key` is a raw 32-byte AES key stored **inside** the sealed read-body
/// — it is NOT an ECIES hex string (semantic type change, D-07/NODE-02).
/// `encryption_mode` is mandatory; do not normalise to GCM-only (CTR drives
/// large-file range reads).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VersionEntry {
    pub version_id: String,
    pub cid: String,

pub fn build_child_refs(
    child_read_key: &[u8; 32],
    child_write_key: &[u8; 32],
    parent_read_key: &[u8; 32],
    parent_write_key: &[u8; 32],
    child_id: &str,
    ipns_name: &str,
    name: &str,
    kind: NodeKind,
    generation: u32,
    version_floor: u64,
) -> Result<(SealedChildRef, WriteChildRef), SdkError> {
    let read_key_sealed_bytes =
        seal::seal_child_read_key(child_read_key, parent_read_key, child_id, kind, generation)?;
    let read_key_sealed = STANDARD.encode(read_key_sealed_bytes);

    let write_key_sealed_bytes = seal::seal_child_write_key(
        child_write_key,
        parent_write_key,
        child_id,
        kind,
        generation,
    )?;
    let write_key_sealed = STANDARD.encode(write_key_sealed_bytes);

    let sealed_child_ref = SealedChildRef {
        name: name.to_string(),
        ipns_name: ipns_name.to_string(),
        generation,
        version_floor,
        read_key_sealed,
    };

    let write_child_ref = WriteChildRef {
        child_id: child_id.to_string(),
        write_key_sealed,
    };

    Ok((sealed_child_ref, write_child_ref))
}

