/// Parses a `PublishedNode::kind` wire string back to its [`NodeKind`]
/// (the inverse of [`NodeKind::as_str`]) — fail-closed on an unknown value.
fn node_kind_from_str(kind: &str) -> Result<NodeKind, RotationError> {
    match kind {
        "folder" => Ok(NodeKind::Folder),
        "file" => Ok(NodeKind::File),
        "root" => Ok(NodeKind::Root),
        other => Err(RotationError::RotateFailed(format!(
            "rebuild_rotated_write_sealed: unknown node kind {other:?}"
        ))),
    }
}

/// Re-seals a rotated node's write plane from the locally-mounted
/// `InodeTable`, so a read-key rotation republish PRESERVES `write_sealed`
/// instead of dropping it to `None` (see the module doc comment). Mirrors the
/// write-plane half of `CipherBoxFS::build_folder_metadata`: rebuilds
/// `write_children` from the node's child inodes (each child's WRITE key is
/// stable across a read-key rotation, so this is rotation-independent) and
/// seals `NodeWriteBody { ipns_private_key, write_children }` under the node's
/// OWN (stable) write key at the NEW `generation`, via the `ROLE_BODY` AAD
/// that [`seal_node`] shares with `seal_published_node`'s write-body path.
///
/// The reconstructed `write_children` may be a SUPERSET of the rotated
/// read-plane children (a covered scope-exit rotation republishes the grant
/// root before its deleted child inode is unlinked). That is harmless:
/// `list_folder_owned` iterates the READ children and looks each write child
/// up by id (`crates/sdk/src/listing.rs`), so an extra unmatched write child
/// is never read, while a MISSING one fails closed — and this loop skips the
/// exact same non-linkable children (`build_folder_metadata` parity) so the
/// write plane is never a subset of the read plane.
///
/// Returns `Ok(None)` when the node is not locally materialized — the node
/// then keeps the prior `write_sealed: None` behavior rather than erroring,
/// mirroring the fail-closed signing-seed lookup in [`ApiClientTransport`].
fn rebuild_rotated_write_sealed(
    inodes: &InodeTable,
    ipns_name: &str,
    node_id: &str,
    kind: NodeKind,
    generation: u32,
) -> Result<Option<String>, RotationError> {
    let Some(node_inode) = inodes.inodes.values().find(|inode| match &inode.kind {
        InodeKind::Root { ipns_name: n, .. }
        | InodeKind::Folder { ipns_name: n, .. }
        | InodeKind::File { ipns_name: n, .. } => n == ipns_name,
    }) else {
        return Ok(None);
    };

    let (self_read_key, self_write_key, ipns_private_key) = match &node_inode.kind {
        InodeKind::Root {
            read_key,
            write_key,
            ipns_private_key,
            ..
        }
        | InodeKind::Folder {
            read_key,
            write_key,
            ipns_private_key,
            ..
        }
        | InodeKind::File {
            read_key,
            write_key,
            ipns_private_key,
            ..
        } => (**read_key, **write_key, ipns_private_key.to_vec()),
    };

    let mut write_children: Vec<WriteChildRef> = Vec::new();
    for &child_ino in node_inode.children.as_deref().unwrap_or_default() {
        let child = inodes.get(child_ino).ok_or_else(|| {
            RotationError::RotateFailed(format!(
                "rebuild_rotated_write_sealed: child inode {child_ino} not found for {ipns_name}"
            ))
        })?;
        let (child_kind, child_ipns, child_read_key, child_write_key) = match &child.kind {
            InodeKind::Folder {
                ipns_name,
                read_key,
                write_key,
                ..
            } => (NodeKind::Folder, ipns_name.clone(), **read_key, **write_key),
            InodeKind::File {
                ipns_name,
                read_key,
                write_key,
                ..
            } => (NodeKind::File, ipns_name.clone(), **read_key, **write_key),
            // Non-File/Folder inodes are not read-plane children — the normal
            // republish path (`build_folder_metadata`) skips them too.
            InodeKind::Root { .. } => continue,
        };
        // Never-published child (no IPNS identity yet): nothing to link — the
        // normal republish path skips it too, keeping both planes symmetric.
        if child_ipns.is_empty() {
            continue;
        }
        let (_sealed_ref, write_ref) = cipherbox_sdk::build_child_refs(
            &child_read_key,
            &child_write_key,
            &self_read_key,
            &self_write_key,
            &child.node_id,
            &child_ipns,
            &child.name,
            child_kind,
            0,
            0,
        )
        .map_err(|e| {
            RotationError::RotateFailed(format!(
                "rebuild_rotated_write_sealed: build_child_refs failed for child {child_ino}: {e}"
            ))
        })?;
        write_children.push(write_ref);
    }

    let write_body = NodeWriteBody {
        ipns_private_key,
        write_children,
    };
    let wb_bytes = encode_write_body(&write_body).map_err(|e| {
        RotationError::RotateFailed(format!(
            "rebuild_rotated_write_sealed: encode_write_body failed for {ipns_name}: {e}"
        ))
    })?;
    let sealed = seal_node(&wb_bytes, &self_write_key, node_id, kind, generation).map_err(|e| {
        RotationError::RotateFailed(format!(
            "rebuild_rotated_write_sealed: seal failed for {ipns_name}: {e}"
        ))
    })?;
    Ok(Some(STANDARD.encode(sealed)))
}

