    /// On-demand spawn of a SINGLE FilePointer async resolution for `ino`,
    /// reading the file's CURRENT node/v3 `read_key` from the inode at spawn
    /// time. Returns `true` if a fresh task was spawned.
    ///
    /// The folder-refresh spawn loop captures each file's `read_key` when the
    /// parent folder is populated. If that key is later ROTATED (a scope-exit
    /// read-key rotation — `write_ops::grant_scope`) while a resolution is in
    /// flight, the captured key no longer matches the republished node and the
    /// resolution fails to unseal (`AES-GCM decryption failed`), even though
    /// `refresh_rotated_inode_read_keys` has already updated the INODE to the
    /// new key. This lets the read path re-drive a fresh resolution with the
    /// POST-rotation inode key so a rotated file becomes readable again.
    ///
    /// This is what lets a covered overwrite-rename land on macOS FUSE-T: the
    /// SMB overwrite-rename `open()`s the source file (Linux's kernel `rename`
    /// never does), and that `open` would otherwise EIO on the stale-key
    /// resolution failure and fail the whole rename.
    ///
    /// No-op (`false`) when a resolution is already in flight, or the inode is
    /// gone / not a File / already resolved (non-empty `cid`) / has no IPNS
    /// identity yet.
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub(crate) fn spawn_filepointer_resolution(&mut self, ino: u64) -> bool {
        if self.resolving_file_pointers.contains(&ino) {
            return false;
        }
        let (ipns, read_key) = match self.inodes.get(ino).map(|i| &i.kind) {
            Some(crate::inode::InodeKind::File {
                ipns_name,
                read_key,
                cid,
                ..
            }) if cid.is_empty() && !ipns_name.is_empty() => (ipns_name.clone(), **read_key),
            _ => return false,
        };
        self.resolving_file_pointers.insert(ino);
        let api = self.api.clone();
        let tx = self.filepointer_tx.clone();
        let high_water = self.high_water.clone();
        self.rt.spawn(async move {
            let result = tokio::time::timeout(
                NETWORK_TIMEOUT,
                crate::content_ops::resolve_file_descriptors(&api, &high_water, &ipns, &read_key),
            )
            .await;
            match result {
                Ok(Ok((cid, iv, size, encryption_mode))) => {
                    let _ = tx.send(PendingFilePointer::Success {
                        ino,
                        cid,
                        iv,
                        size,
                        encryption_mode,
                    });
                }
                Ok(Err(e)) => {
                    log::warn!("FilePointer on-demand resolve failed for ino {}: {}", ino, e);
                    let _ = tx.send(PendingFilePointer::Failure { ino });
                }
                Err(_) => {
                    log::warn!(
                        "FilePointer on-demand resolve timed out for ino {} ({}s)",
                        ino,
                        NETWORK_TIMEOUT.as_secs()
                    );
                    let _ = tx.send(PendingFilePointer::Failure { ino });
                }
            }
        });
        true
    }
}

